n = int(input())
import os,resource
from pathlib import Path
Path('resource.txt').write_text('x')
_,hard=resource.getrlimit(resource.RLIMIT_NOFILE)
resource.setrlimit(resource.RLIMIT_NOFILE,(32,hard))
fds=[]; result='within_limit'
try:
 for _ in range(20 if n == 1 else 2):
  try: fds.append(os.open('resource.txt',os.O_RDONLY))
  except OSError as error:
   if error.errno != 24: raise
   result='limited'; break
 print(result)
finally:
 for fd in fds: os.close(fd)

